# --- Hand-written: tenant isolation and grants ---------------------------------------------

TENANT_EXPR = "nullif(current_setting('app.tenant_id', true), '')::uuid"
BYPASS_EXPR = "current_setting('app.bypass_rls', true) = 'on'"


def _enable_rls_and_grants() -> None:
    from app.core.config import get_settings

    role = get_settings().db_app_role
    if not role.replace("_", "").isalnum():
        raise ValueError("invalid DB_APP_ROLE")
    for table in ("cms_connections", "cms_deliveries"):
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} "
            f"USING (tenant_id = {TENANT_EXPR} OR {BYPASS_EXPR}) "
            f"WITH CHECK (tenant_id = {TENANT_EXPR} OR {BYPASS_EXPR})"
        )
        op.execute(f"GRANT SELECT, INSERT, UPDATE ON {table} TO {role}")
